package com.chilicraft.quest;
import com.chilicraft.core.gui.GuiHolder; import net.kyori.adventure.text.Component; import net.kyori.adventure.text.minimessage.MiniMessage; import org.bukkit.Material; import org.bukkit.entity.Player; import org.bukkit.inventory.ItemStack; import java.util.*;
final class QuestGui { private final QuestService service; private final QuestSettings settings; QuestGui(QuestService s,QuestSettings q){service=s;settings=q;} void open(Player p){GuiHolder h=new GuiHolder(54,text(settings.guideTitle));int slot=10;for(var ch:service.chapters())for(var q:ch.quests()){var state=service.progress(p.getUniqueId()).state(ch.id(),q.id());h.set(slot++,item(Material.BOOK,text("<gold>"+q.title()),List.of(text("<gray>"+state.name()))),(pl,type)->{if(type.isLeftClick())openDetail(pl,q.chapterId(),q.id());else if(type.isRightClick())service.claim(pl,q.id(),result->{if(result.status()==com.chilicraft.api.QuestRewardStatus.SUCCESS)pl.sendMessage(settings.message("claimed","已领取任务奖励。"));else if(result.status()==com.chilicraft.api.QuestRewardStatus.ALREADY_CLAIMED)pl.sendMessage(settings.message("already-claimed","该任务奖励已领取。"));else pl.sendMessage(settings.message("claim-failed","任务奖励领取失败，请稍后重试。"));});});}h.set(49,item(Material.BARRIER,text("<red>关闭"),List.of()),(pl,t)->pl.closeInventory());h.open(p);}private void openDetail(Player p,String c,String id){QuestDefinition q=service.chapters().stream().flatMap(x->x.quests().stream()).filter(x->x.chapterId().equals(c)&&x.id().equals(id)).findFirst().orElse(null);if(q==null)return;GuiHolder h=new GuiHolder(27,text(settings.detailTitle));var s=service.progress(p.getUniqueId());h.set(13,item(Material.WRITTEN_BOOK,text("<gold>"+q.title()),List.of(text("<gray>"+q.description()),text("<gray>进度："+s.progress(c,id)+"/"+q.target().amount()),text("<gray>状态："+s.state(c,id).name()))));h.set(22,item(Material.ARROW,text("<yellow>返回"),List.of()),(pl,t)->open(pl));h.open(p);}private Component text(String s){return MiniMessage.miniMessage().deserialize(s);}private ItemStack item(Material m,Component n,List<Component> l){ItemStack i=new ItemStack(m);var meta=i.getItemMeta();meta.displayName(n);meta.lore(l);i.setItemMeta(meta);return i;}}
